HTREEITEM anode(State& s,HWND tree,app::DoorEntryKind kind,unsigned target){auto& rows=tree==s.navigation?s.doors.navigation_items:s.doors.tree_items;for(std::size_t i=0;i<rows.size();++i){const auto item=rows[i];if(!item.group&&item.entry.kind==kind&&item.entry.target==target)return item.handle;if(tree==s.navigation)door_navigation_expand(s,item.handle);else door_tree_expand(s,item.handle);}throw std::runtime_error("action node missing");}
